<template><div v-if="auth.isLoggedIn" class="notif-wrap"><button class="notification" @click="open=!open">🔔<span v-if="unread" class="notif-count">{{unread>9?'9+':unread}}</span></button><div v-if="open" class="notif-pop"><div class="notif-head"><b>Notifications</b><button class="ghost" @click="markAll">Mark all read</button></div><div v-if="items.length"><div v-for="n in items" :key="n._id" class="notice" :class="{unread:!n.read}" @click="read(n)"><b>{{n.title}}</b><p>{{n.message}}</p><small>{{formatDateTime(n.createdAt)}}</small></div></div><EmptyState v-else title="No notifications yet" message="New account, prediction and result updates will appear here." icon="🔔" compact /></div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useAuth} from '../stores/auth';import {api} from '../services/api';import {formatDateTime} from '../utils/formatters';import {useToast} from '../composables/feedback';import EmptyState from './EmptyState.vue';const auth=useAuth(),open=ref(false),items=ref<any[]>([]),unread=ref(0),{show:toast}=useToast();async function load(){try{const d=await api.get('/me/notifications');items.value=d.data||[];unread.value=d.unread||0}catch{toast('Notifications could not be loaded.','error','Notifications')}}async function read(n:any){if(!n.read){try{await api.patch(`/me/notifications/${n._id}/read`,{});n.read=true;unread.value=Math.max(0,unread.value-1)}catch{toast('We could not mark this notification as read.','error','Notification')}}}async function markAll(){try{await api.patch('/me/notifications/read-all',{});items.value.forEach(n=>n.read=true);unread.value=0}catch{toast('We could not update your notifications.','error','Notifications')}}onMounted(load)</script>
